    # Uniform rows and columns are dividers between panels.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    wall = grid[div_rows[0]][0] if div_rows else None

    excluded = set(div_rows)
    excluded_cols = set(div_cols)
    counts = {}
    for r in range(h):
        for c in range(w):
            if r not in excluded and c not in excluded_cols:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    background = max(counts, key=counts.get)

    row_bounds = [-1] + div_rows + [h]
    col_bounds = [-1] + div_cols + [w]
    out = [[background for _ in range(len(col_bounds) - 1)]
           for _ in range(len(row_bounds) - 1)]

    for i in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
        for j in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color == background or color == wall:
                        continue
                    if ((r + 1 < r1 and grid[r + 1][c] == color) or
                        (c + 1 < c1 and grid[r][c + 1] == color)):
                        out[i][j] = 1
                        break
                if out[i][j] == 1:
                    break
    return out
