def transform(grid):
    h, w = len(grid), len(grid[0])

    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_edges = [-1] + divider_rows + [h]
    col_edges = [-1] + divider_cols + [w]

    divider_cells = set(divider_rows)
    divider_columns = set(divider_cols)
    counts = {}
    for r in range(h):
        if r in divider_cells:
            continue
        for c in range(w):
            if c not in divider_columns:
                color = grid[r][c]
                counts[color] = counts.get(color, 0) + 1

    background = max(counts, key=counts.get)
    marker_counts = {color: n for color, n in counts.items()
                     if color != background}
    marker = max(marker_counts, key=marker_counts.get) if marker_counts else None

    output = []
    for ri in range(len(row_edges) - 1):
        r0, r1 = row_edges[ri] + 1, row_edges[ri + 1]
        row = []
        for ci in range(len(col_edges) - 1):
            c0, c1 = col_edges[ci] + 1, col_edges[ci + 1]
            occurrences = sum(
                grid[r][c] == marker
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if occurrences >= 2 else background)
        output.append(row)
    return output
